type op struct{ from, to int; amt int64; reply chan error }

// owner goroutine: single writer, so no lock is needed at all
for {
    select {
    case o := <-ops:
        if bal[o.from] < o.amt {
            o.reply <- errors.New("insufficient")   // caller retries or aborts
            continue
        }
        bal[o.from] -= o.amt
        bal[o.to] += o.amt
        o.reply <- nil
    }
}

// caller
for {
    err := do(op{from, to, amt, make(chan error, 1)})
    if err != ErrRetry { return err }
}
